import{_ as t,c as n,o as i,ag as s}from"./chunks/framework.bCALENAD.js";const m=JSON.parse('{"title":"Fehlerbehebung","description":"","frontmatter":{},"headers":[],"relativePath":"de/troubleshooting.md","filePath":"de/troubleshooting.md","lastUpdated":1720813934000}'),d={name:"de/troubleshooting.md"};function l(a,e,o,r,u,c){return i(),n("div",null,[...e[0]||(e[0]=[s('<h1 id="fehlerbehebung" tabindex="-1">Fehlerbehebung <a class="header-anchor" href="#fehlerbehebung" aria-label="Permalink to &quot;Fehlerbehebung&quot;">​</a></h1><p>In diesem Guide erfährst du, wie du bekannte Fehler mit diesem Dienst behebst.</p><div class="danger custom-block"><p class="custom-block-title">Could not open the database file. Maybe it is damaged?</p><p>Bei diesem Fehler kann es mehrere Lösungen geben. Arbeite einfach alle Möglichkeiten durch und dein Problem sollte gelöst sein. 😃</p><ol><li><p>Berechtigungen setzen<br> Um die Berechtigungen zu setzen, gib den Befehl <code>chmod 700 /opt/myspeed</code> ein. (Ersetze /opt/myspeed mit deinem Installationsort)</p></li><li><p>Build Essentials Installieren<br> Es ist aktuell möglich, dass der Fehler auftritt, weil das Paket <code>build-essential</code> nicht installiert ist. Installiere es ganz einfach mit dem Befehl <code>sudo apt-get install build-essential</code> nach.</p></li><li><p>Führe eine Neuinstallation der Module aus<br> Gib zuerst den Befehl <code>rm -R node_modules</code> im Installationsordner ein, um die Module zu löschen und installiere sie dann mit <code>npm install</code> nach.</p></li></ol></div><div class="danger custom-block"><p class="custom-block-title">Diese MySpeed-Instanz befindet sich aktuell im Entwicklungsmodus</p><p>Das ist nicht wirklich ein Fehler, lediglich eine Sicherung um das Tool nur in Produktionsumgebungen verwenden zu können. Setze dazu die Umgebungsvariable <code>NODE_ENV</code> auf den Wert <code>production</code>.</p><p>Unter Linux erreichst du das mit <code>export NODE_ENV=production</code> und unter Windows in der Powershell mit <code>$env:NODE_ENV=&quot;production&quot;</code>.</p><p>Lies dir auch mal den <a href="./setup/linux">Guide zur 24/7 Installation</a> durch, wenn du planst, MySpeed im Hintergrund laufen zu lassen und beim Systemstart automatisch hochzufahren.</p></div>',4)])])}const p=t(d,[["render",l]]);export{m as __pageData,p as default};
